"""Restore the exact frozen OPEC test samples from the 3 November 2026 test run.

Run from the project folder: python tests/fixtures/restore_opec_samples.py
Writes only tests/fixtures/opec/. Existing different files are never overwritten.
Uses Python's standard library; no internet access or package installation.
The encoded section contains public report pages, expected values and source fingerprints.
"""
import base64
import hashlib
import json
from pathlib import Path
import zlib


def main():
    root = Path.cwd().resolve()
    if not (root / "tests" / "conftest.py").is_file() or not (root / "pipeline" / "opec_momr.py").is_file():
        raise SystemExit("Run this script from your iraqdata project folder.")
    directory = root / "tests" / "fixtures" / "opec"
    if not directory.resolve().is_relative_to(root):
        raise SystemExit("The sample folder must be inside the project folder.")
    records = json.loads(zlib.decompress(base64.b85decode("".join(PAYLOAD.split()))))
    pending = []
    for record in records:
        name = record["name"]
        if Path(name).name != name or name in (".", "..") or "/" in name or "\\" in name:
            raise SystemExit("Invalid embedded sample filename.")
        body = base64.b64decode(record["body"], validate=True)
        if hashlib.sha256(body).hexdigest() != record["sha256"]:
            raise SystemExit("Embedded sample fingerprint mismatch: " + name)
        target = directory / name
        if target.exists():
            if not target.is_file() or target.read_bytes() != body:
                raise SystemExit("Existing sample differs; nothing written: " + str(target))
        else:
            pending.append((target, body))
    directory.mkdir(parents=True, exist_ok=True)
    for target, body in pending:
        with target.open("xb") as stream:
            stream.write(body)
    print(f"OPEC test samples ready: {len(records)} files ({len(pending)} created).")


